package com.example.deviceguard;
import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.deviceguard.models.*;import com.example.deviceguard.network.*;import com.example.deviceguard.utils.*;import com.google.android.gms.maps.*;import com.google.android.gms.maps.model.*;import retrofit2.*;
public class MapActivity extends AppCompatActivity implements OnMapReadyCallback{
 private GoogleMap map;private String deviceId,deviceName;private Marker marker;private SessionManager s;private ApiService api;private SocketManager socket;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_map);deviceId=getIntent().getStringExtra("deviceId");deviceName=getIntent().getStringExtra("deviceName");s=new SessionManager(this);api=RetrofitClient.get(this);findViewById(R.id.externalMap).setOnClickListener(v->openExternal());SupportMapFragment f=(SupportMapFragment)getSupportFragmentManager().findFragmentById(R.id.map);if(f!=null)f.getMapAsync(this);}
 @Override public void onMapReady(GoogleMap g){map=g;load();socket=new SocketManager();socket.connect(this,s,null,(id,lat,lon)->{if(deviceId.equals(id))runOnUiThread(()->plot(lat,lon));});socket.subscribe(deviceId);}
 private void load(){api.latestLocation(deviceId).enqueue(new Callback<LocationResponse>(){public void onResponse(Call<LocationResponse>c,Response<LocationResponse>r){if(r.isSuccessful()&&r.body().location!=null){LocationPoint p=r.body().location;plot(p.latitude,p.longitude);}else Toast.makeText(MapActivity.this,"No location available yet. Start location sharing on the tracked phone.",Toast.LENGTH_LONG).show();}public void onFailure(Call<LocationResponse>c,Throwable t){Toast.makeText(MapActivity.this,"Network error: "+t.getMessage(),Toast.LENGTH_LONG).show();}});}
 private void plot(double lat,double lon){if(map==null)return;LatLng p=new LatLng(lat,lon);if(marker==null)marker=map.addMarker(new MarkerOptions().position(p).title(deviceName==null?"Device":deviceName));else marker.setPosition(p);map.animateCamera(CameraUpdateFactory.newLatLngZoom(p,16f));}
 private void openExternal(){api.latestLocation(deviceId).enqueue(new Callback<LocationResponse>(){public void onResponse(Call<LocationResponse>c,Response<LocationResponse>r){if(r.isSuccessful()&&r.body().location!=null){LocationPoint p=r.body().location;Intent i=new Intent(Intent.ACTION_VIEW, Uri.parse("geo:"+p.latitude+","+p.longitude+"?q="+p.latitude+","+p.longitude+"("+Uri.encode(deviceName)+")"));startActivity(i);}else Toast.makeText(MapActivity.this,"No location available yet.",Toast.LENGTH_SHORT).show();}public void onFailure(Call<LocationResponse>c,Throwable t){Toast.makeText(MapActivity.this,"Network error",Toast.LENGTH_SHORT).show();}});}
 @Override protected void onDestroy(){if(socket!=null)socket.disconnect();super.onDestroy();}
}
